// 跨分片查询：广播 + 归并
public List<Order> getOrdersByTime(LocalDate date) {
    List<Order> results = new ArrayList<>();
    for (int db = 0; db < DB_COUNT; db++) {
        for (int table = 0; table < TABLE_COUNT_PER_DB; table++) {
            results.addAll(queryShard(db, table, date));
        }
    }
    return results;
}
